  acr                          varchar(64),
  ip_address                   inet,
  user_agent                   varchar(255)
);
COMMENT ON TABLE business_action IS 'Audit trail of business users'' actions through the portal, including object-level and entitlement denials and step-up refusals';
COMMENT ON COLUMN business_action.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN business_action.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN business_action.created_at IS 'Creation time';
COMMENT ON COLUMN business_action.created_by IS 'Principal that created the row';
COMMENT ON COLUMN business_action.business_customer_id IS 'Business customer (from the token)';
COMMENT ON COLUMN business_action.business_user_id IS 'Business user (from the token)';
COMMENT ON COLUMN business_action.action IS 'Operation (operation id of the /v1/business endpoint)';
COMMENT ON COLUMN business_action.object_type IS 'ACCOUNT, PAYMENT, PAYEE, MANDATE, COLLECTION, VIRTUAL_ACCOUNT, PAYMENT_LINK, CARD, LOAN, CREDIT_LINE, FX_QUOTE, STATEMENT, API_CLIENT, WEBHOOK_ENDPOINT, USER, RULE';
COMMENT ON COLUMN business_action.object_id IS 'Object acted on, or the object id that was refused';
COMMENT ON COLUMN business_action.outcome IS 'Result';
COMMENT ON COLUMN business_action.error_code IS 'Problem code when not SUCCEEDED';
COMMENT ON COLUMN business_action.result_id IS 'Id of the record created (payment, approval, card...)';
COMMENT ON COLUMN business_action.auth_age_seconds IS 'Seconds since the user''s last authentication when the action ran';
COMMENT ON COLUMN business_action.acr IS 'Authentication context class of the token';
COMMENT ON COLUMN business_action.ip_address IS 'Client address (right-most X-Forwarded-For hop)';
COMMENT ON COLUMN business_action.user_agent IS 'Client user agent';
CREATE INDEX ix_business_action_tenant ON business_action (tenant_id, created_at);
CREATE INDEX ix_business_action_business_customer_id ON business_action (business_customer_id);
CREATE INDEX ix_business_action_business_user_id ON business_action (business_user_id);
CREATE INDEX ix_business_action_c1 ON business_action (business_customer_id, created_at);
CREATE INDEX ix_business_action_c2 ON business_action (outcome, created_at);
ALTER TABLE business_action ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON business_action USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_business_action_append_only BEFORE UPDATE OR DELETE ON business_action FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium); relayed rows stay for the replay window.
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz
);
COMMENT ON COLUMN outbox.published_at IS 'When the relay published the event (NULL = pending). Relayed rows are kept for the replay window (meridian.events.retention.window) and then purged (MR-GAME-DAY)';
CREATE INDEX ix_outbox_pending ON outbox (created_at, id) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_published ON outbox (published_at) WHERE published_at IS NOT NULL;
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA business_channel TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA business_channel TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA business_channel GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
